-- Rifts World Book 28: Arzno - Vampire Incursion - its bestiary and its notable NPCs.
-- 4 creatures (migration 074) and 0 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~260-arzno-creatures.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO creatures (slug, name, category, system, playable, alignment, attributes, hp, sdc, mdc, ppe, isp, pools_note, ar, horror_factor, combat, bonuses_note, skills_note, natural_abilities, magic, psionics, size, weight, life_span, habitat, allies, enemies, occ_note, description, source_book) VALUES
('waste-ghost', 'Waste Ghost', 'entity', 'rifts', 0, 'None, really; at most Anarchist, since it only copies behavior absorbed from the past', '{"IQ":"5","ME":"2","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"10"}', NULL, NULL, '1D6x10+30', '8', NULL, 'Attributes are not applicable; the book gives equivalents of I.Q. 5 and M.E. 2, and an average speed of about 10. In S.D.C. settings: 6D6+10 Hit Points, no S.D.C. and no A.R.', NULL, 10, '{"attacks":3}', 'Horror Factor 10 when met moving about the Waste, 13 when seen panicking at a Screamer''s scream. +3 to save vs magic and +3 to save vs psionic attack; it always tries to save, even against Empathy or Telepathy. Immune to magic and psionics that act on a physical body. Its three attacks are generally unused: only against someone reaching it by psionics or magic, and then only to flee.', 'None, beyond what it mimics in its endless routine (driving invisible cars, playing sports, working a job and other everyday tasks).', 'Ethereal and intangible: it passes through solid matter and is impervious to all physical and energy attacks. Always visible to the naked eye, and detectable by psionics or magic. It seems unaware of the physical world except through a few psionics and spells, and unlike ordinary Haunting Entities it never uses ectoplasm to take physical form. Connection to Screamers (special): a living being who touches a Waste Ghost or comes within its sensing range sets off an involuntary silent alarm that brings Screamers. The range grows with the ghost population, from 31 feet (9.4 m) on the outer rim to 1050 feet (320 m) at the epicenter. Spirit Warriors go unseen by both the ghosts and the Screamers everywhere but the epicenter until they touch one, and so do Mask Shamans in an Animal, Spirit or Trickster Mask; other Native American Shamans hide themselves and up to eight S.D.C. companions within 100 feet (30.5 m) only while chanting and rubbing a medicine bag. Cannot affect the physical world or break from its adopted routine.', 'None.', 'None.', 'The shape and appearance of the particular human adult or child it imitates', 'Not applicable', 'Presumably immortal', 'Known only in the Waste around the Flagstaff volcano in Arizona; may exist wherever other great tragedies and loss of life occurred', 'Only the other Ghosts of the Waste; many Indian Shamans and compassionate mortals try to see that they are left alone', 'None as such: the Screamers are parasites bound to them rather than enemies, and the only possible foes are people who would destroy them to make the land livable again', 'None; a Haunting Entity.', 'Printed under the heading Ghost of the Waste; also called Waste Spirit or simply Ghost. A Haunting Entity, one of the countless ghosts left where Flagstaff, Arizona and its neighbors died in the eruptions of the Great Cataclysm''s first days. Each copies one person who died there and replays that person''s ordinary life of 2098, feeding on the emotions of the replay; when Screamers howl, the ghosts relive their final moments instead. Astral Projection, Commune with Spirits, Telepathy and Summon and Control Entity give limited contact, but a ghost knows nothing after 2098, and a psychic or mage in contact with one when a Screamer attacks gets no bonus to save against the scream. Encounters run from 1D6 ghosts every half hour on the rim to tens of thousands at the volcano. Its stats are those of the Haunting Entity of Rifts Dark Conversions, adjusted for the Waste. Value: none.', 'Rifts World Book 28: Arzno - Vampire Incursion p.22-24'),
('screamer', 'Screamer', 'entity', 'rifts', 0, 'Miscreant, though driven by instinct and hunger', '{"IQ":"N/A","ME":"N/A","MA":"N/A","PS":"N/A","PP":"N/A","PE":"N/A","PB":"N/A","Spd":"30"}', NULL, NULL, '2D4x10+50', '12', NULL, 'Attributes are not applicable; it moves at a speed of 30 (about 20 mph/32 km). In S.D.C. settings: 6D6+50 Hit Points, no S.D.C. and no A.R.', NULL, 13, '{"attacks":4,"dodge":3}', 'Horror Factor 13 when seen, 16 when screaming. +3 to dodge, and impervious to Horror Factor. Its four attacks go mainly to dodging, since it cannot fight physically; the scream uses none of them.', 'None.', 'Ethereal and intangible: it passes through solid matter, and no physical or energy attack harms it. Normal senses cannot see it; it is revealed by See the Invisible, Astral Projection, Commune with Spirits and similar psionics and magic; thermal imaging shows it as a moving cold spot, and a body it passes near or through feels the chill. Its scream is always heard, by the ears and as a psychic attack. Senses mortals within 1,000 feet (305 m), and races to any Waste Ghost whose alarm it feels. Cannot touch the physical world except through the scream, and apparently cannot cross the border of the Waste.', 'None.', 'Only the scream (see its attacks), a psychic-like ability with no I.S.P. cost.', 'About 2 feet (0.6 m) across, roughly the size of a beach ball', 'Not applicable', 'Unknown; probably immortal', 'Anywhere in the Waste where Waste Ghosts are present; whether it exists elsewhere on Rifts Earth or in the Megaverse is unknown, and its link to the ghosts or the land seems to keep it inside the Waste', 'None, though somehow attuned to the Waste Ghosts', 'Every mortal being, attacked at each chance to feed; the Waste Ghosts are its food rather than its enemies', 'None; an Entity.', 'Printed under the heading Screamer, also known as the Waste Banshee (the name the Waste Ghost text uses, and the survey''s). A red, amorphous sphere of psychic energy drawn to the Waste by the emotions imprinted there, which feeds on fear and pain and gets a high from the suffering its psychic scream causes, in the living and in the Waste Ghosts, who relive their deaths while it howls. Rare or unknown elsewhere, it swarms in the Waste: 1D4 arrive within 3D6 minutes of a human near a ghost on the rim, and 1D6x10 within 1D6 melee rounds at the volcano. All Shamans, the Spirit Warrior and the Mystic Warrior save against the scream at half the usual penalty, and the Paradox Shaman is immune to it. Value: none.', 'Rifts World Book 28: Arzno - Vampire Incursion p.25-27'),
('thumper', 'Thumper', 'humanoid', 'rifts', 1, 'Principled 15%, Scrupulous 70%, Unprincipled 5%, Anarchist 5%, Aberrant 2%, Miscreant 2%, Diabolic 1%', '{"IQ":"2D6+3","ME":"2D6+5","MA":"2D6+5","PS":"2D6+1","PP":"2D6+3","PE":"2D6+5","PB":"1D6+5","Spd":"3D6+2"}', NULL, NULL, 'PE+10+1D6', '4D6', 'ME+1D6+1', 'Minor Mega-Damage being: M.D.C. is the P.E. attribute number +10, plus 1D6 per level of experience starting at level one (stored at level one). I.S.P. is the M.E. attribute number plus 1D6+1 per level of experience (stored at level one). Average Level of Experience 1D6+4.', NULL, 10, '{"attacks":4,"initiative":4,"parry":3,"roll":1}', '+5 to automatic dodge (rolled on a D20, but dodging uses no melee action). +1 attack per melee at levels 5 and 11; +1 to strike with the TK Pulse at levels 2, 5, 8 and 11; +1 to roll with impact at levels 1, 3, 5, 7, 9, 11, 13 and 15 (the level-one +1 is in combat). +1 to save vs poison, +4 to save vs possession; impervious to psychic sensitive communication and attacks (Empathy, Telepathy, Presence Sense, See Aura, Empathic Transmission and the like), and so to the Screamers. No movement or combat penalties from darkness, blindness, deafness, smoke or fog, but heavy rain and overwhelming odors halve the range and skill of its senses and of TK communication. Horror Factor 10 comes from the antennae and the constant thumping (4-6 a melee round, three times that in combat). Rarely uses a weapon or even a fist, relying on the TK Pulse.', 'R.C.C. Skills: Communicate in Native Language 96% (by TK pulse), Climbing 40%/35%, Dowsing 50%, Holistic Medicine 40%, Identify Plants & Fruits 50%, Land Navigation 50%, Prowl 30%, Wilderness Survival 50%; all +5% per level of experience. As a player character the same skills are R.C.C. skills figured normally with bonuses instead: Native Language 98%, Wilderness Survival +15%, Holistic Medicine +5%, Prowl +10%, Identify Plants & Fruits +15%, Land Navigation +14%; plus one new skill without bonuses at levels 2, 4, 6, 8, 10, 12 and 14 from Domestic, Physical, Rogue and Wilderness, with the G.M.''s approval, and never a Language skill. Uses the Dog Boy experience table.', 'Blind, deaf and mute, physically and psionically. It perceives through its telekinetic pulse, the thump: its antennae and touch read the echoes as a detailed 3D image, sharp enough to tell a grape from a pebble. TK pulses also carry Thumper speech by touch, to 500 feet (152 m), 50 feet (15.2 m) in thick forest or indoors, and not through a wall; only one can talk at a time. Its antennae read air temperature and sources of heat or cold, the sun''s position and an engine run within 20 minutes (86% +1% per level); wind and an incoming storm to within 1D6 minutes (82% +1% per level); motion of anything larger than a bullet from any side; and ground or air vibration from vehicles, robots, aircraft or marching troops. Smell identifies most species and devices at 98%, a particular person or animal at 70% +1% per level, a campfire at 2 miles (3.2 km) plus half a mile (0.8 km) per level, trace odors within 20 feet (6.1 m), and strong fresh smells to 300 feet (91.5 m) at 66% +1% per level (+20% touching the source, -20% through layered scents). Touch identifies objects and people. Any attack that blinds or deafens has no effect on it.', 'None.', 'Minor physical psychic: the TK Pulse (special, no I.S.P. cost), TK Lift (6), Levitation (varies) or TK Leap (8), and Resist Fatigue (4) or Impervious to Cold (2). A black hole to psychic sensitives: immune to Telepathy, Empathy and even Presence Sense.', '5 feet to 5 feet 6 inches (1.5-1.7 m)', '100-120 lbs (45-54 kg)', '60 years, usually much shorter in its harsh habitat', 'Chiefly the Waste of Arizona, home to half of the fewer than 20,000 in North America; lone wanderers or groups of up to eight anywhere in Arizona, New Mexico, northern Mexico and the lowlands of the southern Rocky Mountains', 'None as such; it keeps to itself, but is known to lead travelers under attack by Screamers to the edge of the Waste', 'Large carnivorous predators, and humans and D-Bees who take it for a monster; Waste Ghosts and Screamers ignore it', 'Optional R.C.C. (p.28-29), which the book says to allow only sparingly as a player character; uses the Dog Boy experience table. Ruling D19 gives it a class as well as this row.', 'A gentle, nomadic D-Bee of the Waste: a lanky humanoid with bright yellow skin covered in twitching antennae (2D6+12 on its small eyeless, earless head, a dozen down the spine, 1D6+6 on the chest and on each limb, all 6-12 inches/15-30 cm long), flat padded feet that make it quiet but slow, and three long fingers on each hand. Named for the heartbeat-like thump of its telekinetic sonar. Peaceful, it lives off the land and relies on the ghosts and Screamers, which ignore it, to keep people away; threatened, it knocks foes down with its TK pulse and escapes. Value: none.', 'Rifts World Book 28: Arzno - Vampire Incursion p.27-29'),
('waste-monkey', 'Waste Monkey', 'animal', 'rifts', 1, 'Considered selfish (Unprincipled); does not really know right from wrong', '{"IQ":"1D6+9","ME":"1D4+8","MA":"1D6+12","PS":"1D6+7","PP":"2D4+8","PE":"1D6+6","PB":"1D6+9","Spd":"1D6+10"}', 'PE+1D4', '2D6+10', NULL, '3D6', NULL, 'Hit Points are the P.E. attribute number plus 1D4 per level of experience (stored at level one). An S.D.C. creature. Its I.Q. is a highly intelligent animal''s: a child of 4-5 in some ways, with the cunning of a 14-15 year old.', NULL, NULL, '{"attacks":4,"initiative":1,"strike":1,"parry":1,"dodge":3,"pull_punch":1,"roll":3}', 'In addition to possible attribute bonuses. +1 to pull punch (or bite). +2 to save vs Horror Factor. Horror Factor: not applicable.', 'R.C.C. Skills: Camouflage 55%, Climbing 70%/60%, Escape Artist 65%, Identify Plants & Fruits 86%, Land Navigation 79%, Prowl 60%, Wilderness Survival 85%. As a player character these do not advance; it also picks three Secondary Skills at level one from Basic Mechanics (-10%), Dance, Concealment, Gymnastics (+5%), Palming (+2%), Play Musical Instrument (-10%), Pick Locks, Pick Pockets, Sign Language (-10%), Swimming (-15%), Tailing and Language (understanding only), and one more at levels 2, 4, 7, 10 and 13; those advance. Uses the Vagabond experience table.', 'Nimble and quick, it walks on the knuckles of its spade-like forepaws and handles things with prehensile feet as deft as human hands. Digs at one-third of its running speed. Nightvision 500 feet (152 m). Understands spoken language better than a dog or chimp and picks up commands and vocabulary fast, though it can only hoot and holler. A gifted problem solver, almost impossible to keep caged or shut in.', 'None.', 'None.', '2-3 feet (0.6-0.9 m) tall standing fully erect', '13-18 lbs (5.9-8 kg)', '25-30 years', '87% live only in the Waste, 10% around it (especially Phoenix and the Clarkdale Confederacy) and 3% in the mountain forests of Arizona and parts of New Mexico; 50,000-70,000 in all. Prefers warm climates and does poorly in cold or strongly seasonal places.', 'None as such; it likes Thumpers, and readily befriends humans and D-Bees who feed it and treat it well', 'Predators, especially canines, felines and Tiger Claw Raptors; also cowboys, Native Americans, adventurers and Great Trade Road merchants who catch it as a pet or for resale. It runs from the Screamers'' noise, but neither disturbs Waste Ghosts nor draws Screamers.', 'Optional R.C.C. (p.30-31): the book says it suits a G.M.''s NPC better, though a player may take one; uses the Vagabond experience table. Ruling D19 gives it a class as well as this row.', 'Also called the Shovel-Paw Monkey: a primate half again the size of a Spider Monkey, with a stub of a tail, spade-like hooves in place of hands for digging up grubs and roots, and prehensile feet, so it moves on its knuckles with its feet swinging below. Perhaps descended from escaped zoo animals, a product of genetic engineering, or from another dimension. It lives in lodges of 3-10 mated pairs, in hollows dug beneath rock, roots or wrecked vehicles, the females raising the young and the males foraging and fighting. Curious, clever and playful, it raids the Clarkdale Confederacy in pairs, makes a fine pet (and a thief''s accomplice) once caught, and fights fiercely for its friends with teeth and shovel-hands. Value: as much as 100 credits as a pet, more as a novelty outside Arizona and New Mexico.', 'Rifts World Book 28: Arzno - Vampire Incursion p.29-31');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('creature', 'screamer', 'Scream, physical component', NULL, 0, NULL, 'Save 16 or better (P.E. bonuses apply) or be deafened and wracked with pain: attacks per melee fall to two, all combat bonuses -8, no Called or Aimed Shots, Spd halved, skills -60%, spell casters cast half as many spells, and a 01-75% chance of falling for each 10 feet (3 m) moved. A successful save halves the penalties and removes the falls. A helmet or plugged ears give +2 to save, environmental armor or sound filtering +5; shutting off all hearing and radio gives immunity to this part, at the cost of total deafness. Sustained indefinitely; uses none of its attacks.', 0),
('creature', 'screamer', 'Scream, psychic component', NULL, 0, NULL, 'Save vs psionics at -4 at the start of each melee round or lose one M.E. point; at M.E. 1 the victim falls into a coma for 3D6 minutes and the Screamer leaves. M.E. returns at one point a minute. A failed save also rolls once on the book''s emotion table (p.26-27): from mild fright through helplessness, panic, terror and flight, screaming, sorrow, anguish, and psychosomatic deafness or blindness, with cumulative penalties lasting until the screaming stops or the victim leaves the Waste, lingering effects afterward, and on most results a 01-33% chance of a phobia or obsession.', 1),
('creature', 'thumper', 'TK Pulse', '1D6', 0, '100 feet (30 m)', 'S.D.C., plus knockdown: anything under 300 lbs (135 kg) is thrown 1D6+6 yards/meters back, with a 01-70% chance of knocking a two-legged being off its feet (55% for four or more legs, 35% for 301-500 lbs/135.5-225 kg). Those knocked down lose initiative and two attacks that melee, and have a 01-20% chance of dropping what they hold. Each pulse is one attack; used to defend and escape.', 0),
('creature', 'thumper', 'Punch', '1D4', 0, NULL, 'S.D.C.', 1),
('creature', 'thumper', 'Kick', '2D4', 0, NULL, 'S.D.C.', 2),
('creature', 'waste-monkey', 'Bite', '1D6', 0, NULL, 'S.D.C.', 0),
('creature', 'waste-monkey', 'Clawing foot', '1D4', 0, NULL, 'S.D.C.', 1),
('creature', 'waste-monkey', 'Shovel hand', '1D6+1', 0, NULL, 'S.D.C.', 2);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 4 creatures are in' AS assertion, count(*) AS got, 4 AS want
  FROM creatures WHERE slug IN ('waste-ghost', 'screamer', 'thumper', 'waste-monkey');
SELECT 'and 2 of them are playable' AS assertion, count(*) AS got, 2 AS want
  FROM creatures WHERE playable = 1 AND slug IN ('waste-ghost', 'screamer', 'thumper', 'waste-monkey');
SELECT 'the creatures carry 8 attacks' AS assertion, count(*) AS got, 8 AS want
  FROM stat_attacks WHERE owner_kind = 'creature' AND owner_slug IN ('waste-ghost', 'screamer', 'thumper', 'waste-monkey');

